def _elapsed_ms(value):
    """历史 detail 里的 elapsed 是秒（float），转成毫秒整数；缺省/非法返回 None"""
    if value is None or str(value).strip() == '':
        return None
    try:
        return max(0, int(round(float(value) * 1000)))
    except (TypeError, ValueError):
        return None


def backfill_tool_breakdown(apps, schema_editor):
    """尽力回填既有工具调用留痕的三维度快照

    历史行的 agent / elapsed 在 detail JSON 里，来源名在 target（display）前缀里；
    解析失败的行保持空值，查询时会归入「未记录」，不影响统计可用性。
    """
    AuditLog = apps.get_model('users', 'AuditLog')
    pending = []
    rows = AuditLog.objects.filter(action__in=TOOL_ACTIONS).only('id', 'detail', 'target')
    for row in rows.iterator(chunk_size=500):
        try:
            detail = json.loads(row.detail or '{}')
        except (TypeError, ValueError):
            detail = {}
        if not isinstance(detail, dict):
            detail = {}

        agent = str(detail.get('agent') or '')[:200]
        elapsed = _elapsed_ms(detail.get('elapsed'))
        text = str(row.target or '')
        if '·' in text:
            source = text.split('·', 1)[0].strip()[:200]
        elif text:
            source = '平台内置'
        else:
            source = ''

        if agent or source or elapsed is not None:
            pending.append(AuditLog(
                id=row.id, agent_name=agent, source_name=source, elapsed_ms=elapsed))

    if pending:
        AuditLog.objects.bulk_update(
            pending, ['agent_name', 'source_name', 'elapsed_ms'], batch_size=500)


